import { useState, useEffect, useCallback, useMemo } from 'react';
import { CompleteSessionSummary, NationalDevelopmentSummary } from '../../../shared/types';
import { fetchCompleteSessionSummary, fetchLiveSummary, API_BASE } from '../../../infrastructure/api/api';

export type PostSessionSection = 'overview' | 'summary_points' | 'members' | 'topics';

/**
 * SubTopicItem — now derived from REAL transcript-based agenda discussions,
 * NOT from static/hardcoded data.
 *
 * Generated by backend/services/ai.service.ts → generateLiveSummary()
 * which filters transcripts to relevance >= 0.38 and organises them by
 * agenda topic.
 */
export interface SubTopicItem {
  id: string;
  title: string;
  category: string;
  key_points: string[];
}

// Static data completely removed — all categories are derived from real agenda topics
export const POINT_CATEGORIES_STATIC: string[] = ["ALL"];

/**
 * Convert the backend agenda_topic_discussions into SubTopicItem[]
 * so the existing LegislativeSummaryNotesTab UI renders without changes.
 */
function buildSubTopicsFromSummary(summary: NationalDevelopmentSummary | null): SubTopicItem[] {
  if (!summary) return [];

  // Use the new agenda_topic_discussions field (topics with relevant sentences)
  if (summary.agenda_topic_discussions && summary.agenda_topic_discussions.length > 0) {
    return summary.agenda_topic_discussions.map(td => ({
      id: td.topic_id,
      title: td.topic_title,
      category: "Agenda Discussion",
      key_points: td.sentences.map(s => `${s.speaker}: ${s.text}`)
    }));
  }

  // Fallback: if only key_topics available (older API shape) build simplified cards
  if (summary.key_topics && summary.key_topics.length > 0) {
    return summary.key_topics.map((t, i) => ({
      id: `T${String(i + 1).padStart(2, "0")}`,
      title: t.title,
      category: "Key Topic",
      key_points: [t.description]
    }));
  }

  return [];
}

export function usePostSessionViewModel() {
  const [summaryData,     setSummaryData]     = useState<CompleteSessionSummary | null>(null);
  const [liveSummary,     setLiveSummary]      = useState<NationalDevelopmentSummary | null>(null);
  const [isLoading,       setIsLoading]        = useState(true);
  const [error,           setError]            = useState<string | null>(null);
  const [memberFilter,    setMemberFilter]     = useState("");
  const [activeSection,   setActiveSection]    = useState<PostSessionSection>("overview");
  const [pointSearchQuery, setPointSearchQuery] = useState("");
  // Category filter: derived from real topic titles
  const [pointCategoryFilter, setPointCategoryFilter] = useState("ALL");

  const loadSummary = useCallback(async () => {
    setIsLoading(true);
    setError(null);
    try {
      // Fetch both: the complete summary (scorecards, stats) AND
      // the agenda-relevance-filtered live summary (discussion content)
      const [complete, live] = await Promise.allSettled([
        fetchCompleteSessionSummary(),
        fetchLiveSummary()
      ]);

      if (complete.status === "fulfilled") setSummaryData(complete.value);
      else throw new Error((complete.reason as any)?.message || "Failed to load session summary");

      if (live.status === "fulfilled") setLiveSummary(live.value);
      // live summary failure is non-fatal — UI shows empty state

    } catch (err: any) {
      console.error("[Summary] Failed to load:", err);
      setError(err?.message || "Failed to load session summary. Please check connection.");
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => { loadSummary(); }, [loadSummary]);

  const handleExportJSON = () => {
    if (!summaryData) return;
    const exportData = { ...summaryData, agenda_summary: liveSummary };
    const blob = new Blob([JSON.stringify(exportData, null, 2)], { type: "application/json" });
    const url  = URL.createObjectURL(blob);
    const a    = document.createElement("a");
    a.href     = url;
    a.download = `PARLIAMENTARY_REPORT_${summaryData.session_information.session_id}.json`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const handlePrint = () => window.print();

  // Build SubTopicItem[] from REAL live summary data (no static data)
  const allSubTopics: SubTopicItem[] = useMemo(
    () => buildSubTopicsFromSummary(liveSummary),
    [liveSummary]
  );

  // Derive category list from real topic titles
  const POINT_CATEGORIES: string[] = useMemo(() => {
    const cats = Array.from(new Set(allSubTopics.map(t => t.category)));
    return ["ALL", ...cats];
  }, [allSubTopics]);

  const filteredSubTopics = useMemo(() => {
    return allSubTopics.filter(item => {
      const matchesCat  = pointCategoryFilter === "ALL" || item.category === pointCategoryFilter;
      const matchesQuery =
        pointSearchQuery === "" ||
        item.title.toLowerCase().includes(pointSearchQuery.toLowerCase()) ||
        item.id.toLowerCase().includes(pointSearchQuery.toLowerCase()) ||
        item.key_points.some(p => p.toLowerCase().includes(pointSearchQuery.toLowerCase()));
      return matchesCat && matchesQuery;
    });
  }, [allSubTopics, pointCategoryFilter, pointSearchQuery]);

  const filteredMembers = useMemo(() => {
    if (!summaryData) return [];
    return summaryData.member_wise_summary.filter(m =>
      m.name.toLowerCase().includes(memberFilter.toLowerCase()) ||
      m.seat_id.toLowerCase().includes(memberFilter.toLowerCase()) ||
      m.member_id.toLowerCase().includes(memberFilter.toLowerCase()) ||
      (m.member_summary?.discussion_summary &&
        m.member_summary.discussion_summary.toLowerCase().includes(memberFilter.toLowerCase())) ||
      (m.member_summary?.policy_keywords &&
        m.member_summary.policy_keywords.some(k => k.toLowerCase().includes(memberFilter.toLowerCase())))
    );
  }, [summaryData, memberFilter]);

  return {
    summaryData,
    liveSummary,
    isLoading,
    error,
    memberFilter,       setMemberFilter,
    activeSection,      setActiveSection,
    pointCategoryFilter, setPointCategoryFilter,
    pointSearchQuery,   setPointSearchQuery,
    filteredMembers,
    filteredSubTopics,
    POINT_CATEGORIES,
    loadSummary,
    handleExportJSON,
    handlePrint
  };
}

export type PostSessionViewModel = ReturnType<typeof usePostSessionViewModel>;
